(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit31-trap-c3-advanced-1"]={"id":"unit31-trap-c3-advanced-1","unitId":"3-1","chapterIds":["3-1"],"unitType":"advanced","group":"3-1단원 · 선지 변형 유형 · 순서","name":"심화 1","level":"심화","revision":1,"originPage":"unit31","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"순서","parts":[{"name":"U31-P07-03-S1 · 순서","items":[{"paragraphCount":1,"readingLabel":"7문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 7문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 7문단]\n프롬은 현대인의 이러한 태도가 20세기 후반에 일어난 결혼 제도의 큰 변화와 결부되어 있다고 본다. 과거 19세기나 20세기 전반까지만 해도 연인이 서로 사랑해서 결혼하지는 않았다. 결혼은 부부가 될 사람들의 부모에 의해서 이루어졌다. 이러한 혼인 제도가 지배하는 상황에서 사람들은 사랑이란 결혼의 조건이 아니고 결혼 후에 가꾸어 가는 것으로 생각했다. 그러나 20세기 후반부터는 연인이 서로 사랑에 빠져서 결혼해야 한다는 ‘낭만적인 사랑’의 관념이 지배하게 되었다. 이와 함께 사람들은 사랑을 가꾸어 가는 것보다는 사랑에 빠질 상대를 만나는 것이 가장 중요하다고 생각하게 되었다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["순서"],"why":"부모가 결혼을 정하던 때에는 결혼한 뒤에 사랑을 가꾸면 된다고 생각했다.\n근거: “이러한 혼인 제도가 지배하는 상황에서 사람들은 사랑이란 결혼의 조건이 아니고 결혼 후에 가꾸어 가는 것으로 생각했다.”\n7문단에서 확인할 수 있어요.","evidence":{"title":"과거 사랑은 결혼 후 가꾸는 것이었다.","statement":"부모가 결혼을 정하던 때에는 결혼한 뒤에 사랑을 가꾸면 된다고 생각했다.","explanation":"부모가 결혼을 정하던 때에는 결혼한 뒤에 사랑을 가꾸면 된다고 생각했다.\n근거: “이러한 혼인 제도가 지배하는 상황에서 사람들은 사랑이란 결혼의 조건이 아니고 결혼 후에 가꾸어 가는 것으로 생각했다.”\n7문단에서 확인할 수 있어요.","valid":["R07:4"],"sources":[{"id":"R07","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"7문단","sentences":[{"id":"R07:1","text":"프롬은 현대인의 이러한 태도가 20세기 후반에 일어난 결혼 제도의 큰 변화와 결부되어 있다고 본다.","paragraph":0,"memberIds":["R07:1"],"topic":"프롬은 현대인의 이런 태도가 20세기 후반에 결혼 제도가 크게 바뀐 것과 이어져(결부되어) 있다고 본다."},{"id":"R07:2","text":"과거 19세기나 20세기 전반까지만 해도 연인이 서로 사랑해서 결혼하지는 않았다.","paragraph":0,"memberIds":["R07:2"],"topic":"예전(19세기나 20세기 전반)까지만 해도 두 사람이 서로 사랑해서 결혼하지는 않았다."},{"id":"R07:3","text":"결혼은 부부가 될 사람들의 부모에 의해서 이루어졌다.","paragraph":0,"memberIds":["R07:3"],"topic":"결혼은 부부가 될 사람들의 부모가 정했다."},{"id":"R07:4","text":"이러한 혼인 제도가 지배하는 상황에서 사람들은 사랑이란 결혼의 조건이 아니고 결혼 후에 가꾸어 가는 것으로 생각했다.","paragraph":0,"memberIds":["R07:4"],"topic":"이런 결혼 방식이 당연하던 때에는, 사랑을 결혼하기 위한 조건으로 보지 않았다. 결혼한 뒤에 가꾸어 가는 것이라고 생각했다."},{"id":"R07:5","text":"그러나 20세기 후반부터는 연인이 서로 사랑에 빠져서 결혼해야 한다는 ‘낭만적인 사랑’의 관념이 지배하게 되었다.","paragraph":0,"memberIds":["R07:5"],"topic":"그런데 20세기 후반부터는 '서로 사랑에 빠져서 결혼해야 한다'는 생각, 곧 '낭만적인 사랑'이라는 생각(관념)이 당연한 것이 되었다(지배하게 되었다)."},{"id":"R07:6","text":"이와 함께 사람들은 사랑을 가꾸어 가는 것보다는 사랑에 빠질 상대를 만나는 것이 가장 중요하다고 생각하게 되었다.","paragraph":0,"memberIds":["R07:6"],"topic":"그러면서 사람들은 사랑을 가꾸어 가는 것보다, 사랑에 빠질 상대를 만나는 것이 가장 중요하다고 생각하게 되었다."}]}]},"id":"U31-P07-03-S1","type":"mc","sent":"7문단의 내용과 맞는 설명은?","options":["부모가 결혼을 정하던 때에는 결혼한 뒤에 사랑을 가꾸면 된다고 생각했다.","부모가 결혼을 정하던 때에는 먼저 사랑에 빠져야 결혼할 수 있다고 생각했다.","프롬은 현대인이 사랑을 생각하는 방식이 20세기 후반의 결혼 제도 변화와 관련 없다고 본다.","19세기나 20세기 전반에는 부모가 아니라 연인들 스스로 결혼을 정했다.","20세기 후반에는 '서로의 사랑보다 부모의 결정에 따라 결혼해야 한다'는 생각이 널리 퍼졌다."],"answer":"부모가 결혼을 정하던 때에는 결혼한 뒤에 사랑을 가꾸면 된다고 생각했다.","choiceReviews":{"부모가 결혼을 정하던 때에는 결혼한 뒤에 사랑을 가꾸면 된다고 생각했다.":{"reason":"부모가 결혼을 정하던 때에는 결혼한 뒤에 사랑을 가꾸면 된다고 생각했다.\n근거: “이러한 혼인 제도가 지배하는 상황에서 사람들은 사랑이란 결혼의 조건이 아니고 결혼 후에 가꾸어 가는 것으로 생각했다.”\n7문단에서 확인할 수 있어요.","edits":[]},"부모가 결혼을 정하던 때에는 먼저 사랑에 빠져야 결혼할 수 있다고 생각했다.":{"reason":"바르게 고치면: 부모가 결혼을 정하던 때에는 결혼한 뒤에 사랑을 가꾸면 된다고 생각했다.\n부모가 결혼을 정하던 때에는 결혼한 뒤에 사랑을 가꾸면 된다고 생각했다.\n근거: “이러한 혼인 제도가 지배하는 상황에서 사람들은 사랑이란 결혼의 조건이 아니고 결혼 후에 가꾸어 가는 것으로 생각했다.”\n7문단에서 확인할 수 있어요.","edits":[{"start":16,"end":37,"before":"먼저 사랑에 빠져야 결혼할 수 있다고 ","after":"결혼한 뒤에 사랑을 가꾸면 된다고 "}]},"프롬은 현대인이 사랑을 생각하는 방식이 20세기 후반의 결혼 제도 변화와 관련 없다고 본다.":{"reason":"바르게 고치면: 프롬은 현대인이 사랑을 생각하는 방식이 20세기 후반의 결혼 제도 변화와 관련 있다고 본다.\n프롬은 현대인이 사랑을 생각하는 방식이 20세기 후반의 결혼 제도 변화와 관련 있다고 본다.\n근거: “프롬은 현대인의 이러한 태도가 20세기 후반에 일어난 결혼 제도의 큰 변화와 결부되어 있다고 본다.”\n7문단에서 확인할 수 있어요.","edits":[{"start":44,"end":48,"before":"없다고 ","after":"있다고 "}]},"19세기나 20세기 전반에는 부모가 아니라 연인들 스스로 결혼을 정했다.":{"reason":"바르게 고치면: 19세기나 20세기 전반에는 부모가 자녀의 결혼을 정했다.\n19세기나 20세기 전반에는 부모가 자녀의 결혼을 정했다.\n근거: “결혼은 부부가 될 사람들의 부모에 의해서 이루어졌다.”\n7문단에서 확인할 수 있어요.","edits":[{"start":20,"end":32,"before":"아니라 연인들 스스로 ","after":"자녀의 "}]},"20세기 후반에는 '서로의 사랑보다 부모의 결정에 따라 결혼해야 한다'는 생각이 널리 퍼졌다.":{"reason":"바르게 고치면: 20세기 후반에는 '서로 사랑에 빠져서 결혼해야 한다'는 생각이 널리 퍼졌다.\n20세기 후반에는 '서로 사랑에 빠져서 결혼해야 한다'는 생각이 널리 퍼졌다.\n근거: “그러나 20세기 후반부터는 연인이 서로 사랑에 빠져서 결혼해야 한다는 ‘낭만적인 사랑’의 관념이 지배하게 되었다.”\n7문단에서 확인할 수 있어요.","edits":[{"start":10,"end":31,"before":"'서로의 사랑보다 부모의 결정에 따라 ","after":"'서로 사랑에 빠져서 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"25f5914175936ffe78df823fdc1596d1d52b8c24dedb469f87084403aaca3e3c"}]},{"name":"U31-P08-05-S1 · 순서","items":[{"paragraphCount":1,"readingLabel":"8문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 8문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 8문단]\n셋째로 현대인은 멋진 상대를 만나 그에게 빠지는 것이 곧 사랑이라고 생각하기 때문에, 사랑에 처음 빠지는 순간 경험하는 격정적인 상태와 사랑이 지속되는 상태를 혼동한다. 두 연인 사이에 있던 벽이 갑자기 허물어지면서 두 사람이 완전히 하나가 된 것처럼 느끼는 상태야말로 우리가 맛볼 수 있는 가장 황홀한 기분이다. 그러나 이런 사랑은 오래 지속될 수 없다. 두 사람이 서로에 대해서 더 깊이 알게 될수록, 처음에 기적처럼 생겼던 친밀감은 갈수록 약화된다. 시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["순서"],"why":"'콩깍지가 벗겨진다'는 상대를 무조건 좋게 보던 마음이 사라진다는 뜻이다. 처음과 달리 상대에게 실망하거나 싫증을 느끼게 된다.\n근거: “시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.”\n8문단에서 확인할 수 있어요.","evidence":{"title":"설렘 대신 실망과 권태가 자리한다.","statement":"상대의 단점이 보이기 시작하면 처음의 기대와 설렘 대신 실망과 싫증을 느낀다.","explanation":"'콩깍지가 벗겨진다'는 상대를 무조건 좋게 보던 마음이 사라진다는 뜻이다. 처음과 달리 상대에게 실망하거나 싫증을 느끼게 된다.\n근거: “시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.”\n8문단에서 확인할 수 있어요.","valid":["R08:5"],"sources":[{"id":"R08","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"8문단","sentences":[{"id":"R08:1","text":"셋째로 현대인은 멋진 상대를 만나 그에게 빠지는 것이 곧 사랑이라고 생각하기 때문에, 사랑에 처음 빠지는 순간 경험하는 격정적인 상태와 사랑이 지속되는 상태를 혼동한다.","paragraph":0,"memberIds":["R08:1"],"topic":"셋째, 현대인은 멋진 상대에게 빠지는 것이 곧 사랑이라고 생각한다. 그래서 처음 빠졌을 때의 뜨겁게 들뜬(격정적인) 상태와, 사랑이 오래 이어지는(지속되는) 상태를 헷갈린다(혼동한다)."},{"id":"R08:2","text":"두 연인 사이에 있던 벽이 갑자기 허물어지면서 두 사람이 완전히 하나가 된 것처럼 느끼는 상태야말로 우리가 맛볼 수 있는 가장 황홀한 기분이다.","paragraph":0,"memberIds":["R08:2"],"topic":"두 사람 사이의 벽이 갑자기 무너지고, 완전히 하나가 된 것처럼 느끼는 상태가 있다. 이것이야말로 우리가 느낄 수 있는 가장 황홀한 기분이다."},{"id":"R08:3","text":"그러나 이런 사랑은 오래 지속될 수 없다.","paragraph":0,"memberIds":["R08:3"],"topic":"그러나 이런 사랑은 오래갈 수 없다."},{"id":"R08:4","text":"두 사람이 서로에 대해서 더 깊이 알게 될수록, 처음에 기적처럼 생겼던 친밀감은 갈수록 약화된다.","paragraph":0,"memberIds":["R08:4"],"topic":"두 사람이 서로를 더 깊이 알게 될수록, 처음에 기적처럼 생긴 가까운 느낌(친밀감)은 점점 약해진다."},{"id":"R08:5","text":"시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.","paragraph":0,"memberIds":["R08:5"],"topic":"흔히 하는 말로 '눈에 씐 콩깍지가 벗겨지면' 처음의 기대·설렘·즐거움은 사라진다. 그 자리에 서로에 대한 실망, 환멸(기대가 깨져 싫어지는 마음), 권태감(지루하고 싫증 나는 느낌)이 들어선다."}]}]},"id":"U31-P08-05-S1","type":"mc","sent":"8문단의 내용과 맞는 설명은?","options":["상대의 단점이 보이기 시작해도 처음의 기대와 설렘만 커지고 실망과 싫증은 사라진다.","현대인은 처음 사랑에 빠졌을 때의 뜨거운 감정이 오래 사랑하는 것과 다르다는 점을 분명히 안다.","연인들은 갑자기 아주 가까워져 하나가 된 것처럼 느낀다. 이때 가장 큰 싫증을 느낀다.","처음 사랑에 빠졌을 때의 큰 행복과 설렘은 변하지 않고 영원히 이어진다.","상대의 단점이 보이기 시작하면 처음의 기대와 설렘 대신 실망과 싫증을 느낀다."],"answer":"상대의 단점이 보이기 시작하면 처음의 기대와 설렘 대신 실망과 싫증을 느낀다.","choiceReviews":{"상대의 단점이 보이기 시작하면 처음의 기대와 설렘 대신 실망과 싫증을 느낀다.":{"reason":"'콩깍지가 벗겨진다'는 상대를 무조건 좋게 보던 마음이 사라진다는 뜻이다. 처음과 달리 상대에게 실망하거나 싫증을 느끼게 된다.\n근거: “시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.”\n8문단에서 확인할 수 있어요.","edits":[]},"상대의 단점이 보이기 시작해도 처음의 기대와 설렘만 커지고 실망과 싫증은 사라진다.":{"reason":"바르게 고치면: 상대의 단점이 보이기 시작하면 처음의 기대와 설렘 대신 실망과 싫증을 느낀다.\n'콩깍지가 벗겨진다'는 상대를 무조건 좋게 보던 마음이 사라진다는 뜻이다. 처음과 달리 상대에게 실망하거나 싫증을 느끼게 된다.\n근거: “시쳇말로 눈에서 콩깍지가 벗겨지면서 처음에 느꼈던 기대와 설렘 그리고 즐거움 대신에, 서로에 대한 실망과 환멸 그리고 권태감이 자리하게 된다.”\n8문단에서 확인할 수 있어요.","edits":[{"start":12,"end":17,"before":"시작해도 ","after":"시작하면 "},{"start":25,"end":33,"before":"설렘만 커지고 ","after":"설렘 대신 "},{"start":37,"end":46,"before":"싫증은 사라진다.","after":"싫증을 느낀다."}]},"현대인은 처음 사랑에 빠졌을 때의 뜨거운 감정이 오래 사랑하는 것과 다르다는 점을 분명히 안다.":{"reason":"바르게 고치면: 현대인은 처음 사랑에 빠졌을 때의 뜨거운 감정이 오래 사랑하는 것과 같다고 생각한다.\n사랑에 처음 빠진 순간의 감정과 사랑을 오래 이어 가는 일은 다르다. 현대인은 이 두 가지를 같은 것으로 생각한다.\n근거: “셋째로 현대인은 멋진 상대를 만나 그에게 빠지는 것이 곧 사랑이라고 생각하기 때문에, 사랑에 처음 빠지는 순간 경험하는 격정적인 상태와 사랑이 지속되는 상태를 혼동한다.”\n8문단에서 확인할 수 있어요.","edits":[{"start":38,"end":53,"before":"다르다는 점을 분명히 안다.","after":"같다고 생각한다."}]},"연인들은 갑자기 아주 가까워져 하나가 된 것처럼 느낀다. 이때 가장 큰 싫증을 느낀다.":{"reason":"바르게 고치면: 연인들은 갑자기 아주 가까워져 하나가 된 것처럼 느낀다. 이때 가장 큰 행복과 설렘을 느낀다.\n'벽이 허물어진다'는 두 사람 사이의 거리감이 사라진다는 뜻이다. 실제로 벽이 무너진다는 말은 아니다.\n근거: “두 연인 사이에 있던 벽이 갑자기 허물어지면서 두 사람이 완전히 하나가 된 것처럼 느끼는 상태야말로 우리가 맛볼 수 있는 가장 황홀한 기분이다.”\n8문단에서 확인할 수 있어요.","edits":[{"start":40,"end":44,"before":"싫증을 ","after":"행복과 설렘을 "}]},"처음 사랑에 빠졌을 때의 큰 행복과 설렘은 변하지 않고 영원히 이어진다.":{"reason":"바르게 고치면: 처음 사랑에 빠졌을 때의 큰 행복과 설렘은 오래 이어질 수 없다.\n처음 사랑에 빠졌을 때의 큰 행복과 설렘은 오래 이어질 수 없다.\n근거: “그러나 이런 사랑은 오래 지속될 수 없다.”\n8문단에서 확인할 수 있어요.","edits":[{"start":24,"end":40,"before":"변하지 않고 영원히 이어진다.","after":"오래 이어질 수 없다."}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"1f9b1575c166e571fd00beab823ae7aa098009f3b08003c12d18e2dd929a35ad"}]},{"name":"U31-P11-05-S1 · 순서","items":[{"paragraphCount":1,"readingLabel":"11문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 11문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 11문단]\n우리는 흔히 사람들이 주는 것보다 받는 것을 더 좋아할 것이라고 생각한다. 그러나 사실은 그렇지 않다. 우리는 주는 데서 큰 기쁨을 맛본다. 물질의 영역에서 준다는 것은 자신이 부자임을 의미한다. 많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다. 조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다. 우리는 사람들에게 물질뿐만 아니라 자신의 기쁨, 관심, 지식, 유머 등을 줄 수 있다. 이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다. 그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다. 따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["순서"],"why":"내가 사랑을 주면 상대도 사랑을 주는 사람이 될 수 있다.\n근거: “따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.”\n11문단에서 확인할 수 있어요.","evidence":{"title":"사랑을 받던 사람도 주는 자가 된다.","statement":"내가 사랑을 주면 상대도 사랑을 주는 사람이 될 수 있다.","explanation":"내가 사랑을 주면 상대도 사랑을 주는 사람이 될 수 있다.\n근거: “따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.”\n11문단에서 확인할 수 있어요.","valid":["R11:10"],"sources":[{"id":"R11","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"11문단","sentences":[{"id":"R11:1","text":"우리는 흔히 사람들이 주는 것보다 받는 것을 더 좋아할 것이라고 생각한다.","paragraph":0,"memberIds":["R11:1"],"topic":"우리는 보통 사람들이 주는 것보다 받는 것을 더 좋아할 거라고 생각한다."},{"id":"R11:2","text":"그러나 사실은 그렇지 않다.","paragraph":0,"memberIds":["R11:2"],"topic":"그러나 사실은 그렇지 않다."},{"id":"R11:3","text":"우리는 주는 데서 큰 기쁨을 맛본다.","paragraph":0,"memberIds":["R11:3"],"topic":"우리는 줄 때 큰 기쁨을 맛본다."},{"id":"R11:4","text":"물질의 영역에서 준다는 것은 자신이 부자임을 의미한다.","paragraph":0,"memberIds":["R11:4"],"topic":"돈이나 물건(물질)을 준다는 것은 내가 부자라는 뜻이다."},{"id":"R11:5","text":"많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다.","paragraph":0,"memberIds":["R11:5"],"topic":"많이 가진 사람이 부자가 아니라, 많이 나눠 주는(베푸는) 사람이 부자다."},{"id":"R11:6","text":"조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다.","paragraph":0,"memberIds":["R11:6"],"topic":"조금이라도 잃을까 봐 걱정하는 사람은 아무리 많이 가졌어도 가난한 사람이다."},{"id":"R11:7","text":"우리는 사람들에게 물질뿐만 아니라 자신의 기쁨, 관심, 지식, 유머 등을 줄 수 있다.","paragraph":0,"memberIds":["R11:7"],"topic":"우리는 다른 사람에게 돈이나 물건뿐 아니라 내 기쁨, 관심, 지식, 유머 같은 것도 줄 수 있다."},{"id":"R11:8","text":"이렇게 줌으로써 우리는 다른 사람의 생명을 밝고 충만하게 만든다.","paragraph":0,"memberIds":["R11:8"],"topic":"이렇게 주면서 우리는 다른 사람의 생명(삶)을 밝고 가득 차게(충만하게) 만든다."},{"id":"R11:9","text":"그리고 그렇게 다른 사람의 삶이 밝아지고 충만해지는 것을 보면서 우리도 더욱 밝아지고 충만해진다.","paragraph":0,"memberIds":["R11:9"],"topic":"그리고 다른 사람의 삶이 밝아지고 가득 차는 것을 보면서, 우리도 더 밝아지고 가득 차게 된다."},{"id":"R11:10","text":"따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.","paragraph":0,"memberIds":["R11:10"],"topic":"그러니 사랑을 준다는 것은 상대도 '주는 사람'으로 만드는 일이다. 그리고 두 사람 모두 더 큰 활기(생명력)를 갖게 되는 관계에 함께하는(참여하는) 일이다."}]}]},"id":"U31-P11-05-S1","type":"mc","sent":"11문단의 내용과 맞는 설명은?","options":["내가 사랑을 주면 상대는 계속 받기만 하는 사람으로 남는다.","사람은 받을 때만 기쁘다. 줄 때는 기쁨을 느끼지 못한다.","글쓴이는 남에게 많이 베푸는 사람보다 많이 쌓아 두기만 하는 사람을 진정한 부자라고 본다.","내가 사랑을 주면 상대도 사랑을 주는 사람이 될 수 있다.","우리는 다른 사람에게 물건만 줄 수 있다."],"answer":"내가 사랑을 주면 상대도 사랑을 주는 사람이 될 수 있다.","choiceReviews":{"내가 사랑을 주면 상대도 사랑을 주는 사람이 될 수 있다.":{"reason":"내가 사랑을 주면 상대도 사랑을 주는 사람이 될 수 있다.\n근거: “따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.”\n11문단에서 확인할 수 있어요.","edits":[]},"내가 사랑을 주면 상대는 계속 받기만 하는 사람으로 남는다.":{"reason":"바르게 고치면: 내가 사랑을 주면 상대도 사랑을 주는 사람이 될 수 있다.\n내가 사랑을 주면 상대도 사랑을 주는 사람이 될 수 있다.\n근거: “따라서 사랑을 준다는 것은 다른 사람도 주는 자로 만드는 것이며, 두 사람 모두가 더욱 큰 생명력을 갖게 되는 관계에 참여하는 것을 의미한다.”\n11문단에서 확인할 수 있어요.","edits":[{"start":10,"end":33,"before":"상대는 계속 받기만 하는 사람으로 남는다.","after":"상대도 사랑을 주는 사람이 될 수 있다."}]},"사람은 받을 때만 기쁘다. 줄 때는 기쁨을 느끼지 못한다.":{"reason":"바르게 고치면: 사람은 받을 때뿐 아니라 줄 때도 큰 기쁨을 느낀다.\n사람은 받을 때뿐 아니라 줄 때도 큰 기쁨을 느낀다.\n근거: “우리는 주는 데서 큰 기쁨을 맛본다.”\n11문단에서 확인할 수 있어요.","edits":[{"start":7,"end":15,"before":"때만 기쁘다. ","after":"때뿐 아니라 "},{"start":17,"end":20,"before":"때는 ","after":"때도 큰 "},{"start":24,"end":32,"before":"느끼지 못한다.","after":"느낀다."}]},"글쓴이는 남에게 많이 베푸는 사람보다 많이 쌓아 두기만 하는 사람을 진정한 부자라고 본다.":{"reason":"바르게 고치면: 글쓴이는 많이 가진 사람보다 남에게 많이 베푸는 사람을 진정한 부자라고 본다.\n여기서 '부자'는 가진 물건의 양으로 정하지 않는다. 다른 사람에게 많이 베풀 수 있는 사람을 가리킨다.\n근거: “많이 가진 자가 부자가 아니라 많이 베푸는 자가 부자다.” “조금이라도 잃어버릴까 걱정하는 자는 아무리 많이 갖고 있더라도 가난한 자다.”\n11문단에서 확인할 수 있어요.","edits":[{"start":0,"end":5,"before":"글쓴이는 ","after":"글쓴이는 많이 가진 사람보다 "},{"start":16,"end":34,"before":"사람보다 많이 쌓아 두기만 하는 ","after":""}]},"우리는 다른 사람에게 물건만 줄 수 있다.":{"reason":"바르게 고치면: 우리는 다른 사람에게 물건뿐 아니라 기쁨이나 지식도 줄 수 있다.\n우리는 다른 사람에게 물건뿐 아니라 기쁨이나 지식도 줄 수 있다.\n근거: “우리는 사람들에게 물질뿐만 아니라 자신의 기쁨, 관심, 지식, 유머 등을 줄 수 있다.”\n11문단에서 확인할 수 있어요.","edits":[{"start":12,"end":16,"before":"물건만 ","after":"물건뿐 아니라 기쁨이나 지식도 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"83a14035781ac45202735b04ffe04089bf074813504de38fc3493bb035c92f12"}]}]};})(window);
